    s.lines([('A. Karyokinesis: It is the division of the nucleus. "Karyo" means nucleus and "kinesis" means division', 'A. کیریوکائنیسس: یہ مرکزے کی تقسیم ہے۔ ”کیریو“ کا مطلب مرکزہ اور ”کائنیسس“ کا مطلب تقسیم ہے', 'A. کاریوکاینیزس: دا د هستې وېش دی. ”کاریو“ یعنې هسته او ”کاینیزس“ یعنې وېش'),
             ('B. Cytokinesis: It is the division of cytoplasm.', 'B. سائٹوکائنیسس: یہ سائٹوپلازم کی تقسیم ہے۔', 'B. سایټوکاینیزس: دا د سایټوپلازم وېش دی.')])
    s.callout(SI, [('During S phase of interphase, the parent cell makes a copy of each chromosome. In mitosis, the copies of chromosomes are distributed equally to both daughter cells.', 'انٹرفیز کے S مرحلے کے دوران والد خلیہ ہر کروموسوم کی نقل بناتا ہے۔ مائٹوسس میں کروموسومز کی نقلیں دونوں بیٹی خلیوں میں برابر تقسیم ہوتی ہیں۔', 'د انټرفېز د S پړاو پر مهال مور حجره د هر کروموزوم نقل جوړوي. په مایټوزس کې د کروموزومونو نقلونه دواړو لور حجرو ته برابر وېشل کېږي.')])
    s.p('Karyokinesis: It is further divided into four phases i.e. prophase, metaphase, anaphase and telophase.', 'کیریوکائنیسس: اسے مزید چار مراحل یعنی پروفیز، میٹافیز، اینافیز اور ٹیلوفیز میں تقسیم کیا جاتا ہے۔', 'کاریوکاینیزس: دا بیا په څلورو پړاوونو وېشل کېږي یعنې پروفېز، میټافېز، اینافېز او ټیلوفېز.')
